pub interface Measurable {
  fn area(self: &Self) -> Float64;
  fn perimeter(self: &Self) -> Float64;
}

pub type Circle = { radius: Float64; }
pub type Rectangle = { width: Float64; height: Float64; }

impl Measurable for Circle {
  fn area(self: &Circle) -> Float64 { return 3.14159 * self.radius * self.radius; }
  fn perimeter(self: &Circle) -> Float64 { return 2.0 * 3.14159 * self.radius; }
}

impl Measurable for Rectangle {
  fn area(self: &Rectangle) -> Float64 { return self.width * self.height; }
  fn perimeter(self: &Rectangle) -> Float64 { return 2.0 * (self.width + self.height); }
}

fn main() -> Int {
  let c = Circle{ radius: 5.0 };
  let r = Rectangle{ width: 4.0, height: 6.0 };
  if c.area() > r.area() { return 1; }
  return 0;
}
